{
  "name": "rf_cal_process",
  "confidence": "medium",
  "docstring": "Processes an RF calibration packet by optionally assembling a Bluetooth descriptor and copying payload data from a circular calibration buffer.",
  "subsystem": "rf",
  "var_renames": {
    "a1": "cal_ctx",
    "a2": "out_buf",
    "a3": "assemble_bt_desc",
    "a4": "handle_short_payload",
    "v4": "rf_cal_state",
    "v9": "buf_desc",
    "v11": "state_offset",
    "v12": "state_offset",
    "v13": "buf_start",
    "v14": "tail_len",
    "v15": "buf_capacity",
    "v17": "read_ptr"
  },
  "struct_hints": [
    {
      "offset": 8,
      "meaning": "global RF calibration buffer read offset"
    },
    {
      "offset": 7,
      "meaning": "command/subtype byte passed to Bluetooth descriptor assembly"
    },
    {
      "offset": 28,
      "meaning": "calibration context pointer to circular buffer descriptor"
    },
    {
      "offset": 48,
      "meaning": "uint16 total buffered payload length"
    }
  ]
}
